-- Private team sharing for VC Record. Invitation tokens are generated by the
-- browser but only their SHA-256 digest is stored here.
create extension if not exists pgcrypto with schema extensions;

create table public.teams (
  id uuid primary key default gen_random_uuid(),
  name text not null check (char_length(btrim(name)) between 1 and 80),
  invite_hash bytea not null,
  created_by uuid not null references auth.users(id) on delete cascade,
  created_at timestamptz not null default now()
);

create table public.team_members (
  team_id uuid not null references public.teams(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (team_id, user_id)
);

create table public.answers (
  id uuid primary key,
  team_id uuid not null references public.teams(id) on delete cascade,
  owner_user_id uuid not null references auth.users(id) on delete cascade,
  person text not null default '' check (char_length(person) <= 80),
  person_id text not null default '' check (char_length(person_id) <= 200),
  question_id text not null check (question_id ~ '^ipg-(0|[1-9][0-9]?)$' and substring(question_id from 5)::integer <= 76),
  question text not null check (char_length(question) between 1 and 1000),
  created_at timestamptz not null,
  duration double precision not null check (duration >= 0 and duration < 'Infinity'::double precision),
  mime text not null check (char_length(mime) between 1 and 200 and mime ~ '^video/(webm|mp4)(;.*)?$'),
  object_path text not null unique,
  transcript text not null default '' check (char_length(transcript) <= 200000),
  status text not null default 'pending' check (status in ('pending', 'working', 'done', 'error', 'silent')),
  transcript_error text check (transcript_error is null or char_length(transcript_error) <= 4000),
  edited boolean not null default false,
  updated_at timestamptz not null default now(),
  constraint answers_object_path_matches_identity check (
    object_path = team_id::text || '/' || owner_user_id::text || '/' || id::text
  )
);

create index answers_team_created_idx on public.answers (team_id, created_at desc);

alter table public.teams enable row level security;
alter table public.team_members enable row level security;
alter table public.answers enable row level security;

revoke all on public.teams from public, anon, authenticated;
revoke all on public.team_members from public, anon, authenticated;
revoke all on public.answers from public, anon, authenticated;
grant select on public.team_members to authenticated;
grant select, insert, update, delete on public.answers to authenticated;

create policy team_members_read_self on public.team_members
  for select to authenticated using (user_id = (select auth.uid()));

create function public.is_team_member(p_team_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.team_members tm
    where tm.team_id = p_team_id and tm.user_id = (select auth.uid())
  );
$$;
revoke all on function public.is_team_member(uuid) from public, anon;
grant execute on function public.is_team_member(uuid) to authenticated;

create policy answers_read_members on public.answers
  for select to authenticated
  using (public.is_team_member(team_id));
create policy answers_insert_owner_members on public.answers
  for insert to authenticated
  with check (owner_user_id = (select auth.uid()) and public.is_team_member(team_id));
create policy answers_update_owner_members on public.answers
  for update to authenticated
  using (owner_user_id = (select auth.uid()) and public.is_team_member(team_id))
  with check (owner_user_id = (select auth.uid()) and public.is_team_member(team_id));
create policy answers_delete_owner_members on public.answers
  for delete to authenticated
  using (owner_user_id = (select auth.uid()) and public.is_team_member(team_id));

create function public.keep_answer_recording_identity()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.id is distinct from old.id
    or new.team_id is distinct from old.team_id
    or new.owner_user_id is distinct from old.owner_user_id
    or new.person is distinct from old.person
    or new.person_id is distinct from old.person_id
    or new.question_id is distinct from old.question_id
    or new.question is distinct from old.question
    or new.created_at is distinct from old.created_at
    or new.duration is distinct from old.duration
    or new.mime is distinct from old.mime
    or new.object_path is distinct from old.object_path then
    raise exception 'Recording identity and metadata are immutable';
  end if;
  new.updated_at := now();
  return new;
end;
$$;
revoke all on function public.keep_answer_recording_identity() from public, anon, authenticated;
create trigger answers_preserve_recording_identity
  before update on public.answers
  for each row execute function public.keep_answer_recording_identity();

create function public.create_team(p_name text, p_invite_token text)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id uuid := auth.uid();
  v_team_id uuid;
begin
  if v_user_id is null then raise exception 'Authentication required'; end if;
  if p_name is null or char_length(btrim(p_name)) not between 1 and 80 then
    raise exception 'Team name must be between 1 and 80 characters';
  end if;
  if p_invite_token is null or p_invite_token !~ '^[0-9a-fA-F]{64}$' then
    raise exception 'Invitation token must be 64 hexadecimal characters';
  end if;
  insert into public.teams (name, invite_hash, created_by)
  values (btrim(p_name), extensions.digest(decode(lower(p_invite_token), 'hex'), 'sha256'), v_user_id)
  returning id into v_team_id;
  insert into public.team_members (team_id, user_id) values (v_team_id, v_user_id);
  return v_team_id;
end;
$$;
revoke all on function public.create_team(text, text) from public, anon;
grant execute on function public.create_team(text, text) to authenticated;

create function public.join_team(p_team_id uuid, p_invite_token text)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id uuid := auth.uid();
  v_expected_hash bytea;
begin
  if v_user_id is null then raise exception 'Authentication required'; end if;
  if p_invite_token is null or p_invite_token !~ '^[0-9a-fA-F]{64}$' then
    raise exception 'Invalid invitation';
  end if;
  select t.invite_hash into v_expected_hash from public.teams t where t.id = p_team_id;
  if v_expected_hash is null
    or v_expected_hash <> extensions.digest(decode(lower(p_invite_token), 'hex'), 'sha256') then
    raise exception 'Invalid invitation';
  end if;
  insert into public.team_members (team_id, user_id)
  values (p_team_id, v_user_id)
  on conflict (team_id, user_id) do nothing;
  return p_team_id;
end;
$$;
revoke all on function public.join_team(uuid, text) from public, anon;
grant execute on function public.join_team(uuid, text) to authenticated;

-- Bucket policies accept exactly team/owner/answer UUID paths. The helper
-- checks shape before casting path segments, avoiding malformed-path errors.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('recordings', 'recordings', false, 52428800, array['video/*'])
on conflict (id) do update set
  public = false,
  file_size_limit = excluded.file_size_limit,
  allowed_mime_types = excluded.allowed_mime_types;

create function public.can_access_recording(p_name text, p_owner_only boolean default false)
returns boolean
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_parts text[];
  v_team_id uuid;
  v_owner_id uuid;
begin
  if p_name is null or p_name !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    return false;
  end if;
  v_parts := string_to_array(p_name, '/');
  v_team_id := v_parts[1]::uuid;
  v_owner_id := v_parts[2]::uuid;
  if p_owner_only and v_owner_id <> (select auth.uid()) then return false; end if;
  return public.is_team_member(v_team_id);
end;
$$;
revoke all on function public.can_access_recording(text, boolean) from public, anon;
grant execute on function public.can_access_recording(text, boolean) to authenticated;

create policy recordings_read_team on storage.objects
  for select to authenticated
  using (bucket_id = 'recordings' and public.can_access_recording(name, false));
create policy recordings_insert_owner on storage.objects
  for insert to authenticated
  with check (bucket_id = 'recordings' and public.can_access_recording(name, true));
create policy recordings_update_owner on storage.objects
  for update to authenticated
  using (bucket_id = 'recordings' and public.can_access_recording(name, true))
  with check (bucket_id = 'recordings' and public.can_access_recording(name, true));
create policy recordings_delete_owner on storage.objects
  for delete to authenticated
  using (bucket_id = 'recordings' and public.can_access_recording(name, true));
